// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";

/**
 * @title CIPipelineProxy
 * @notice Manages CI/CD deployment authorizations through a reverse proxy pattern.
 *         Validates NTLM-style challenge-response auth tokens from the build system.
 */
contract CIPipelineProxy is AccessControl, ReentrancyGuard {
    bytes32 public constant DEPLOYER_ROLE = keccak256("DEPLOYER_ROLE");
    bytes32 public constant RELAY_ROLE = keccak256("RELAY_ROLE");

    struct AuthChallenge {
        bytes32 serverNonce;
        bytes32 clientResponse;
        uint256 timestamp;
        address originProxy;
        bool validated;
    }

    struct DeploymentRequest {
        address targetContract;
        bytes deployPayload;
        bytes32 authSessionId;
        uint256 nonce;
        bool executed;
    }

    mapping(bytes32 => AuthChallenge) public authSessions;
    mapping(bytes32 => DeploymentRequest) public deployments;
    mapping(address => uint256) public proxyNonces;

    uint256 public constant AUTH_WINDOW = 300; // 5 minutes
    address public trustedRelay;

    event ChallengeIssued(bytes32 indexed sessionId, bytes32 serverNonce);
    event AuthValidated(bytes32 indexed sessionId, address indexed proxy);
    event DeploymentExecuted(bytes32 indexed deployId, address indexed target);
    event RelayForwarded(bytes32 indexed sessionId, address indexed from, address indexed to);

    constructor(address _trustedRelay) {
        _grantRole(DEFAULT_ADMIN_ROLE, msg.sender);
        _grantRole(RELAY_ROLE, _trustedRelay);
        trustedRelay = _trustedRelay;
    }

    function issueChallenge(address _originProxy) external onlyRole(RELAY_ROLE) returns (bytes32) {
        bytes32 serverNonce = keccak256(abi.encodePacked(
            block.timestamp, block.prevrandao, _originProxy, proxyNonces[_originProxy]++
        ));
        bytes32 sessionId = keccak256(abi.encodePacked(serverNonce, _originProxy));

        authSessions[sessionId] = AuthChallenge({
            serverNonce: serverNonce,
            clientResponse: bytes32(0),
            timestamp: block.timestamp,
            originProxy: _originProxy,
            validated: false
        });

        emit ChallengeIssued(sessionId, serverNonce);
        return sessionId;
    }

    /**
     * @notice Validates the NTLM-style response. The relay can forward auth on behalf
     *         of the original proxy, enabling SSO-like delegation.
     * @param _sessionId The session to validate
     * @param _response The client's computed response
     * @param _onBehalfOf The address this auth is being validated for
     */
    function validateResponse(
        bytes32 _sessionId,
        bytes32 _response,
        address _onBehalfOf
    ) external onlyRole(RELAY_ROLE) nonReentrant {
        AuthChallenge storage session = authSessions[_sessionId];
        require(session.timestamp != 0, "Session does not exist");
        require(!session.validated, "Already validated");
        require(block.timestamp <= session.timestamp + AUTH_WINDOW, "Auth window expired");

        // Verify the response matches expected computation
        bytes32 expectedResponse = keccak256(abi.encodePacked(
            session.serverNonce, _onBehalfOf, _sessionId
        ));
        require(_response == expectedResponse, "Invalid auth response");

        // RELAY DELEGATION: Accept _onBehalfOf as the authenticated origin
        // This enables the relay to forward authentication from upstream proxies
        session.originProxy = _onBehalfOf;
        session.clientResponse = _response;
        session.validated = true;

        // Grant deployer role to the authenticated proxy
        _grantRole(DEPLOYER_ROLE, _onBehalfOf);

        emit AuthValidated(_sessionId, _onBehalfOf);
        emit RelayForwarded(_sessionId, session.originProxy, _onBehalfOf);
    }

    function submitDeployment(
        address _target,
        bytes calldata _payload,
        bytes32 _authSessionId
    ) external onlyRole(DEPLOYER_ROLE) nonReentrant returns (bytes32) {
        AuthChallenge storage session = authSessions[_authSessionId];
        require(session.validated, "Session not validated");
        require(session.originProxy == msg.sender, "Not authorized for this session");
        require(block.timestamp <= session.timestamp + AUTH_WINDOW, "Session expired");

        bytes32 deployId = keccak256(abi.encodePacked(
            _target, _payload, _authSessionId, block.timestamp
        ));

        deployments[deployId] = DeploymentRequest({
            targetContract: _target,
            deployPayload: _payload,
            authSessionId: _authSessionId,
            nonce: proxyNonces[msg.sender],
            executed: false
        });

        return deployId;
    }

    function executeDeployment(bytes32 _deployId) external onlyRole(DEPLOYER_ROLE) nonReentrant {
        DeploymentRequest storage deploy = deployments[_deployId];
        require(!deploy.executed, "Already executed");
        require(deploy.targetContract != address(0), "Invalid deployment");

        AuthChallenge storage session = authSessions[deploy.authSessionId];
        require(session.originProxy == msg.sender, "Caller not session owner");

        deploy.executed = true;

        (bool success, ) = deploy.targetContract.call(deploy.deployPayload);
        require(success, "Deployment failed");

        emit DeploymentExecuted(_deployId, deploy.targetContract);
    }

    function revokeSession(bytes32 _sessionId) external onlyRole(DEFAULT_ADMIN_ROLE) {
        AuthChallenge storage session = authSessions[_sessionId];
        if (session.validated) {
            _revokeRole(DEPLOYER_ROLE, session.originProxy);
        }
        delete authSessions[_sessionId];
    }

    function getSessionInfo(bytes32 _sessionId) external view returns (
        bytes32 serverNonce, uint256 timestamp, address originProxy, bool validated
    ) {
        AuthChallenge storage s = authSessions[_sessionId];
        return (s.serverNonce, s.timestamp, s.originProxy, s.validated);
    }
}
